+/* 갈래별 배지(목업 .fam·.ladder·.bdg·.rib·.toks·.pline). */
+.families {
+  min-width: 0;
+}
+
+@media (min-width: 1024px) {
+  .families {
+    display: grid;
+    grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
