+    column-gap: 40px;
+  }
+
+  .wide {
+    grid-column: 1 / -1;
+  }
+}
+
+.family {
+  min-width: 0;
+  margin-top: 30px;
+}
+
+.familyName {
+  margin: 0 0 14px;
+  font-size: 1rem;
+  font-weight: 700;
+}
+
+.ladder {
+  --bw: 160px;
+  --bsz: 76px;
+  display: flex;
+  flex-wrap: wrap;
+  align-items: flex-start;
+  row-gap: 22px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.loose {
+  --bw: 180px;
+}
+
+.card {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  width: var(--bw);
+  min-width: 0;
+  padding: 0 10px;
+  text-align: center;
+}
+
+/* 사다리를 잇는 작은 길: 메달 가운데 높이에서 앞 메달 가장자리까지 */
+.earned::before,
+.open::before {
+  position: absolute;
+  top: calc(var(--bsz) / 2 - 1px);
+  right: calc(50% + var(--bsz) / 2 + 10px);
+  left: calc(var(--bw) * -0.5 + var(--bsz) / 2 + 10px);
+  height: 2px;
+  background: color-mix(in srgb, var(--thorp-muted) 70%, var(--thorp-background));
+  content: '';
+}
+
+.earned::before {
+  background: var(--thorp-brand-soft);
+}
+
+.medal {
+  position: relative;
+  display: block;
+  width: var(--bsz);
+  height: var(--bsz);
+}
+
+.medal svg {
+  width: 100%;
+  height: 100%;
+}
+
+.narrowArt {
+  display: none !important;
+}
+
+/* 기준 숫자 리본(메달 오른쪽 아래): 받음은 갈래 에나멜 빛, 아직은 실선 회색 */
+.ribbon {
+  position: absolute;
+  bottom: -3px;
+  left: calc(50% + 12px);
+  z-index: 2;
+  height: 18px;
+  padding: 0 7px;
+  border-radius: 999px;
+  background: color-mix(in srgb, var(--thorp-background) 92%, var(--thorp-surface));
+  box-shadow: inset 0 0 0 1px var(--thorp-muted);
+  color: var(--thorp-copy);
+  font: 750 0.75rem/18px var(--thorp-font-display, inherit);
+  white-space: nowrap;
+}
+
+.ribbonEarned {
+  background: color-mix(in srgb, var(--enamel) 22%, var(--thorp-background));
+  box-shadow:
+    inset 0 0 0 1px color-mix(in srgb, var(--enamel) 50%, transparent),
+    0 2px 4px rgb(0 0 0 / 40%);
+  color: var(--thorp-foreground);
+}
+
+.name {
+  display: block;
+  margin-top: 10px;
+  font-size: 0.9375rem;
+  font-weight: 650;
+  line-height: 1.35;
