+  떠 있는 '이어서 읽기'(목업 .fab). 깜빡이거나 맥동하지 않는다. 초록 단추의 색·그림자·초점은 greenAction.module.css가
+  정하고, 여기서는 놓이는 자리와 떠 있는 그림자 한 겹을 더한다.
+*/
+.fab {
+  --action-lift: 0 14px 30px -10px rgb(0 0 0 / 80%);
+
+  position: fixed;
+  right: 24px;
+  bottom: 24px;
+  z-index: 40;
+  display: inline-flex;
+  gap: 10px;
+  align-items: center;
+  height: 48px;
+  padding: 0 18px 0 12px;
+  border-radius: 14px;
+}
+
+/* 로그인 상태를 다시 확인하는 동안: 자리를 둔 채 보이지 않게만 한다(research R33). */
+.concealed {
+  visibility: hidden;
+}
+
+/* 단추가 있는 동안 초점을 받은 요소가 단추 밑에 가려지지 않게 아래 스크롤 여백을 둔다(목업 88px). */
+:global(html):has(.fab) {
+  scroll-padding-bottom: 88px;
+}
+
+.fab svg {
+  width: 26px;
+  height: 26px;
+}
+
+.track {
+  fill: color-mix(in srgb, var(--thorp-action-foreground) 18%, transparent);
+}
+
+.arc {
+  fill: none;
+  stroke: var(--thorp-action-foreground);
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  .fab {
+    animation: fab-in 300ms cubic-bezier(0.05, 0.7, 0.1, 1) both;
+  }
+}
+
+@keyframes fab-in {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+}
+
+/* 좁은 화면에서는 양옆 16px을 둔 가로 막대다(목업 720px 미만 .fab). */
+@media (max-width: 719px) {
+  .fab {
+    right: 16px;
+    bottom: 16px;
+    left: 16px;
+    justify-content: center;
+  }
+}
+
+@media (forced-colors: active) {
+  .fab {
+    border: 1px solid ButtonText;
+  }
+}

