+  flex-direction: column;
+  gap: 14px;
+}
+
+.lead {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.9375rem;
+  line-height: 1.6;
+}
+
+.actions {
+  display: flex;
+  justify-content: flex-end;
+}
+
+/* 누르는 곳은 44px 이상이다(design-notes §6). */
+.actions button,
+.dialogActions button {
+  min-height: 44px;
+}
+
+.notice {
+  display: flex;
+  gap: 8px;
+  align-items: center;
+  margin: 0;
+  padding: 12px 16px;
+  border-radius: var(--thorp-radius-card, 12px);
+  background: var(--thorp-accent-muted);
+  color: var(--thorp-foreground);
+  font-size: 0.9375rem;
+}
+
+.dialog {
+  width: min(100% - 32px, 480px);
+  padding: 0;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 16px;
+  background: var(--thorp-surface);
+  color: var(--thorp-foreground);
+}
+
+/* 개편 뒤 생긴 토큰이라 classic에서 비면 예전 값으로 돌아간다(frontend/CLAUDE.md). */
