+  background: var(--thorp-overlay, rgb(3 8 5 / 72%));
+}
+
+.dialogBody {
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  padding: 24px;
+}
+
+.dialogBody h2 {
+  margin: 0;
+  font-size: 1.15rem;
+  font-weight: 750;
+}
+
+.dialogBody p {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.9375rem;
+  line-height: 1.6;
+}
+
+.dialogBody .warning {
+  color: var(--thorp-foreground);
+  font-weight: 650;
+}
+
+.dialogBody .error {
+  color: var(--thorp-negative);
+}
