+/* 단계별 진행의 여섯 정거장(목업 .stations·.station). */
+.stations {
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  margin: 0;
+  padding: 6px 0 0;
+  list-style: none;
+}
+
+.station {
+  position: relative;
+  min-width: 0;
