+/* 정거장 사이의 길: 공개된 단계 사이는 회색 실선, 준비 중 단계로 가는 길은 점선 */
+.station::before {
+  position: absolute;
+  top: 32px;
+  right: calc(50% + 40px);
+  left: calc(-50% + 40px);
+  height: 3px;
+  margin-top: -1.5px;
+  background: color-mix(in srgb, var(--thorp-muted) 70%, var(--thorp-background));
+  content: '';
+}
+
+.station:first-child::before {
