+}
+
+.dashed::before {
+  background: repeating-linear-gradient(
+    to right,
+    color-mix(in srgb, var(--thorp-muted) 70%, var(--thorp-background)) 0 6px,
+    transparent 6px 12px
+  );
+}
+
+.node {
+  position: relative;
