+  inset: 0;
+  width: 64px;
+  height: 64px;
+  overflow: visible;
+}
+
+.number {
+  position: relative;
+}
+
+.plate {
+  fill: var(--thorp-surface);
+  stroke: var(--thorp-muted);
+}
+
+.inner {
+  fill: none;
+  stroke-opacity: 0.28;
+}
+
+.segment {
+  fill: none;
+  stroke: color-mix(in srgb, var(--thorp-muted) 70%, var(--thorp-background));
+}
+
+.segmentRead {
+  fill: none;
+  stroke: var(--thorp-brand-soft);
